def is_valid_schedule(shifts):
    # Check if each shift starts before it ends
    for start, end in shifts:
        if start >= end:
            return False

    # Check if no two shifts overlap
    for i in range(len(shifts)):
        for j in range(i + 1, len(shifts)):
            # Check if shifts i and j overlap
            if shifts[i][1] > shifts[j][0]:
                return False

    # Check if each shift is at least 30 minutes long
    for start, end in shifts:
        if end - start < 30:
            return False

    return True
```

