```python
def is_valid_address(address):
    # Check if the address starts with "k9://"
    if not address.startswith("k9://"):
        return False

    # Split the address into parts after "k9://"
    parts = address[4:].split(":")

    # Check if there's exactly one port number
    if len(parts) != 2:
        return False

    # Check the host part
    host_part = parts[0]
    if not host_part:
        return False  # Host can't be empty

    # Split the host into labels
    labels = host_part.split(".")

    # Check if the host has 2 to 4 labels
    if len(labels) < 2 or len(labels) > 4:
        return False

    # Check each label
    for label in labels:
        if not label:
            return False  # Label can't be empty
        if not label.isalnum() and not label.isdigit():
            return False  # Label must contain only letters and digits
        if len(label) > 8:
            return False  # Label can't be longer than 8 characters

    # Check the port
    port_part = parts[1]
    if not port_part:
        return False  # Port can't be empty
    if not port_part.isdigit():
        return False  # Port must be a number
    port = int(port_part)
    if port < 1024 or port > 49151:
        return False  # Port must be between 1024 and 49151

    return True
```

